SELECT departments.dept_name, CASE WHEN departments.location IN ('Singapore', 'New York') THEN 'priority' ELSE 'other' END AS location_group, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(employees.level))) AS level_values FROM employees JOIN departments ON employees.dept_id = departments.id GROUP BY departments.dept_name, CASE WHEN departments.location IN ('Singapore', 'New York') THEN 'priority' ELSE 'other' END ORDER BY level_values ASC;
